import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeTaskTitle } from './task.js';
test('trims valid input', () => {
  assert.equal(normalizeTaskTitle('  Read  '), 'Read');
});
test('rejects blank input', () => {
  assert.throws(() => normalizeTaskTitle('  '), RangeError);
});
